import 'package:flutter_test/flutter_test.dart';
import 'package:hand_foot_game_flutter/game/game_controller.dart';
import 'package:hand_foot_game_flutter/models/card.dart';

void main() {
  // Exact export from session_17841239000980098 (user paste).
  const export =
      '';

  test(
    'session_17841239000980098: both mid-hand 8s are playable indices',
    () {
      final result = GameController.fromExportJson(export);
      expect(result, isNotNull);
      final gc = result!.controller;
      final human = gc.gameState.players.first;

      expect(human.currentHand[5].rank, CardRank.eight);
      expect(human.currentHand[6].rank, CardRank.eight);

      final indices = gc.getPlayableCardIndices(human);
      expect(indices.contains(5), isTrue, reason: 'first 8 (8♣) playable');
      expect(indices.contains(6), isTrue, reason: 'second 8 (8♠) playable');
    },
    tags: ['regression'],
  );
}
